package com.agon.app

import android.content.Context

/**
 * One admonition shown on the block screen, available in Arabic, Sorani Kurdish and English.
 * The full pool of 150 admonitions is sourced verbatim from block_screen_advice_150.json;
 * the wording is preserved exactly and never merged, shortened or rephrased.
 */
data class Advice(val ar: String, val ku: String, val en: String) {
    fun text(language: String): String = when (language) {
        "ar" -> ar
        "en" -> en
        else -> ku
    }
}

/** Pool of 150 admonitions with a non-repeating random picker. */
object BlockedAdvice {

    private const val PREFS = "blocked_advice"
    private const val KEY_LAST = "last_index"

    /** Random advice, never repeating the previous one back to back. */
    fun next(context: Context): Advice {
        val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        val last = prefs.getInt(KEY_LAST, -1)
        var index = ADVICES.indices.random()
        if (ADVICES.size > 1 && index == last) index = (index + 1) % ADVICES.size
        prefs.edit().putInt(KEY_LAST, index).apply()
        return ADVICES[index]
    }

